-- GENERATED by scripts/export_semantic_layer.py from metrics/registry.yaml and the dbt `meta.semantic` mappings. Do not edit by hand; change the registry or the mapping and regenerate.
--
-- Snowflake semantic view over the dbt-built `analytics` schema. Run it
-- in the database dbt built into (SNOWFLAKE_DATABASE), after
-- `dbt build --target snowflake`. Each metric is named after its
-- registry id.
--
-- Query it with the SEMANTIC_VIEW clause, for example:
--   SELECT * FROM SEMANTIC_VIEW(
--     analytics.bi_framework_metrics
--     METRICS order_items.net_revenue
--     DIMENSIONS order_items.channel
--   );

CREATE OR REPLACE SEMANTIC VIEW analytics.bi_framework_metrics
  TABLES (
    order_items AS analytics.fct_order_items
      PRIMARY KEY (order_item_id)
      COMMENT = 'Order-item grain fact table — the dbt implementation of `base_fact_sql` in metrics/registry.yaml. Filterable dimensions (channel, region, category) live here so registry metrics and LookML measures filter the same rows.',
    customers AS analytics.dim_customers
      PRIMARY KEY (customer_id)
      COMMENT = 'Customer grain, including customers who never ordered. Shared source of "first order", "last order", and 90-day revenue for every cohort metric.',
    channel_acquisition AS analytics.channel_acquisition
      PRIMARY KEY (channel)
      COMMENT = 'Channel grain: total marketing spend and customers whose first order came through the channel. The two additive inputs to CAC, aggregated separately before joining so spend is never fanned out.'
  )
  RELATIONSHIPS (
    order_items_to_customers AS
      order_items (customer_id) REFERENCES customers
  )
  DIMENSIONS (
    order_items.order_date AS order_items.order_date,
    order_items.channel AS order_items.channel,
    order_items.region AS order_items.region,
    order_items.category AS order_items.category,
    customers.acquisition_channel AS customers.acquisition_channel,
    customers.region AS customers.region,
    customers.purchase_outcome AS customers.purchase_outcome,
    customers.first_order_channel AS customers.first_order_channel
      COMMENT = 'Channel of the customer''s first order; the attribution basis for CAC.',
    channel_acquisition.channel AS channel_acquisition.channel
  )
  METRICS (
    order_items.net_revenue AS ROUND(SUM(revenue), 2)
      COMMENT = 'Net Revenue. Total revenue recognized across all order line items in the period. Gross of returns — there is no returns table in the synthetic dataset, so treat this as a simplified top-line figure. [registry:net_revenue; owner: analytics-team; unit: USD]',
    order_items.aov AS ROUND(SUM(revenue) / COUNT(DISTINCT order_id), 2)
      COMMENT = 'Average Order Value. Net revenue divided by the number of distinct orders. Computed at the order grain, not the line-item grain, so multi-item orders aren''t double counted. [registry:aov; owner: analytics-team; unit: USD]',
    customers.repeat_purchase_rate AS ROUND(100.0 * SUM(CASE WHEN order_count >= 2 THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN order_count > 0 THEN 1 ELSE 0 END), 0), 1)
      COMMENT = 'Repeat Purchase Rate. Share of customers with 2+ distinct orders (matching the filter), out of all customers with at least one order matching the filter. In this layer the rate is customer-grain: slice it by customer attributes such as region. It cannot follow order-level channel or category filters the way the registry formula does; use the resolver for those. [registry:repeat_purchase_rate; owner: analytics-team; unit: percent]',
    channel_acquisition.cac_by_channel AS ROUND(SUM(spend) / NULLIF(SUM(acquired_customers), 0), 2)
      COMMENT = 'Customer Acquisition Cost by Channel. Total marketing spend on a channel divided by the number of distinct customers who placed a first order on that channel, over the full dataset window. A cohort metric — not filterable by dimension, since spend and first-order attribution are already channel-grained. Group by channel. [registry:cac_by_channel; owner: growth-team; unit: USD]',
    customers.ltv_90d AS ROUND(AVG(revenue_first_90d), 2)
      COMMENT = '90-Day Customer Lifetime Value. Average net revenue generated per customer within 90 days of their first order. A simplified LTV proxy — no discounting, no margin adjustment — intentionally, to keep the definition auditable at a glance rather than modeling-accurate. A cohort metric — not filterable by dimension in this demo. [registry:ltv_90d; owner: analytics-team; unit: USD]',
    customers.acquisition_funnel AS COUNT(customer_id)
      COMMENT = 'Acquisition Funnel by Channel. For each acquisition channel, how many customers ended up Never Purchased / One-Time Buyer / Repeat Buyer. A cohort metric — uses the customer''s original acquisition_channel (fixed at signup), not the per-order channel used elsewhere in the registry, and isn''t filterable by dimension for the same reason cac_by_channel isn''t. Group by acquisition_channel, purchase_outcome. [registry:acquisition_funnel; owner: growth-team; unit: count]',
    customers.churn_rate_90d AS ROUND(100.0 * SUM(CASE WHEN is_churned_90d THEN 1 ELSE 0 END) / NULLIF(COUNT(is_churned_90d), 0), 1)
      COMMENT = '90-Day Churn Rate. Share of customers whose most recent order is more than 90 days before the dataset''s max order date, i.e. customers who have gone quiet for a full quarter. A snapshot definition, not a rolling one, and not filterable by dimension in this demo. [registry:churn_rate_90d; owner: analytics-team; unit: percent]'
  )
  COMMENT = 'Governed metrics for the bi-framework demo. Generated from metrics/registry.yaml; the registry is the definition of record.';
